    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if v is not None and math.isfinite(v) and v > 0:
        return float(v)
    sites = s.get('sites', ())
    n = sum(max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites)
    v = s.get('lattice', {}).get('volume_A3')
    if v is not None and math.isfinite(v) and v > 0 and n > 0:
        return float(v / n)
    return 0.0

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        r = props.get(e, {}).get('covalent_radius_A')
        if x is not None and math.isfinite(x) and x > 0 and r is not None and math.isfinite(r) and r > 0:
            total += x * r * r * r
            weight += x
    if weight <= 0:
        return 0.0
    return float(4.0 * math.pi * total / (3.0 * weight * v))

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        z = props.get(e, {}).get('valence_electrons')
        if x is not None and math.isfinite(x) and x > 0 and z is not None and math.isfinite(z) and z >= 0:
            total += x * z
            weight += x
    return float(total / (weight * v)) if weight > 0 else 0.0

def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    if n == 0:
        return 0.0
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    near = [math.inf for i in range(n)]
    bonds = s.get('neighbors', ())
    for b in bonds:
        i = b['i']
        j = b['j']
        d = b.get('distance_A')
        if occ[j] > 0 and d is not None and math.isfinite(d) and d > 0:
            near[i] = min(near[i], d)
    cn = [0.0 for i in range(n)]
    for b in bonds:
        i = b['i']
        j = b['j']
        d = b.get('distance_A')
        if occ[j] > 0 and d is not None and math.isfinite(d) and d > 0 and math.isfinite(near[i]) and d <= 2.0 * near[i]:
            cn[i] += occ[j] * math.exp(1.0 - (d / near[i]) ** 6)
    weight = sum(occ)
    if weight <= 0:
        return 0.0
    mean = sum(occ[i] * cn[i] for i in range(n)) / weight
    if mean <= 0:
        return 0.0
    var = sum(occ[i] * (cn[i] - mean) ** 2 for i in range(n)) / weight
    return float(math.sqrt(max(0.0, var)) / mean)

def feature(s):
    props = s.get('element_properties', {})
    data = {}
    numerator = 0.0
    denominator = 0.0
    for e, x in s.get('composition', {}).items():
        if x is None or not math.isfinite(x) or x <= 0:
            continue
        p = props.get(e, {})
        ion = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if ion is None or not math.isfinite(ion) or ion <= 0:
            continue
        if affinity is None or not math.isfinite(affinity):
            affinity = 0.0
        chi = 0.5 * (ion + affinity)
        hardness = max(0.5, ion - affinity)
        data[e] = (chi, hardness)
        numerator += x * chi / hardness
        denominator += x / hardness
    if denominator <= 0:
        return 0.0
    mu = numerator / denominator
    charge = {e: (mu - p[0]) / p[1] for e, p in data.items()}
    sites = s.get('sites', ())
    if len(sites) == 0:
        return 0.0
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    q = [charge.get(t.get('element'), 0.0) for t in sites]
    atoms = sum(occ)
    if atoms <= 0:
        return 0.0
    total = 0.0
    for b in s.get('neighbors', ()):
        i = b['i']
        j = b['j']
        d = b.get('distance_A')
        if d is not None and math.isfinite(d) and d > 0:
            total += occ[i] * occ[j] * q[i] * q[j] * math.exp(-d / 3.0) / d
    return float(0.5 * total / atoms)
